import{_ as t,b as o,c as i,l as n,d as e,k as r}from"./chunks/framework.Yp4hj_cn.js";const b=JSON.parse(`{"title":"Projects","description":"","frontmatter":{"title":"Projects","head":[["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Armaan Gomes"}],["meta",{"property":"og:title","content":"Projects — Armaan Gomes"}],["meta",{"property":"og:description","content":"Hi! I'm Armaan Gomes. I like to build things."}],["meta",{"property":"og:url","content":"https://armaangomes.com/projects"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Projects — Armaan Gomes"}],["meta",{"name":"twitter:description","content":"Hi! I'm Armaan Gomes. I like to build things."}]]},"headers":[],"relativePath":"projects.md","filePath":"projects.md"}`),c={name:"projects.md"};function l(s,a,h,m,p,d){return o(),i("div",null,[...a[0]||(a[0]=[n('<h3 id="hopper-cpu" tabindex="-1">Hopper CPU <a class="header-anchor" href="#hopper-cpu" aria-label="Permalink to “Hopper CPU”">​</a></h3><p>RV32I_ZMMUL CPU deployed on Spartan 7 · Runs <a href="./blogs/doom/">DOOM</a> at 20+ FPS · MIT Open Compute Lab</p><h3 id="clear" tabindex="-1">clEar <a class="header-anchor" href="#clear" aria-label="Permalink to “clEar”">​</a></h3><p>Glasses-frame beamforming hearing aid · 16-mic MEMS array · MSMVDR beamformer · 9.9 dB SNR · 71% STOI · ISEF Grand Award · <a href="https://github.com/arghunter/clEar" target="_blank" rel="noreferrer">github</a> · <a href="/blogs/clear">writeup</a></p><h3 id="supermic" tabindex="-1">Supermic+ <a class="header-anchor" href="#supermic" aria-label="Permalink to “Supermic+”">​</a></h3><p>8 custom ASICs on Tiny Tapeout 8 · SKY130B 130nm · beamforming, audio DSP, PDM signal processing · <a href="https://github.com/arghunter/Supermic-tt08" target="_blank" rel="noreferrer">github</a> · <a href="/blogs/supermic">writeup</a></p><h3 id="acoustic-camera-pdm-operators" tabindex="-1">Acoustic Camera &amp; PDM Operators <a class="header-anchor" href="#acoustic-camera-pdm-operators" aria-label="Permalink to “Acoustic Camera &amp; PDM Operators”">​</a></h3><p>Novel PDM bitstream arithmetic eliminating PCM decimation · 250× runtime speedup on FPGA · ISEF 2nd Place · <a href="https://isef.net/project/ebed041-novel-pdm-operators-for-efficient-beamforming" target="_blank" rel="noreferrer">paper</a></p><h3 id="uc-berkeley-potentiostat" tabindex="-1">UC Berkeley Potentiostat <a class="header-anchor" href="#uc-berkeley-potentiostat" aria-label="Permalink to “UC Berkeley Potentiostat”">​</a></h3><p>18-channel high-speed potentiostat · FPGA data acquisition · real-time C# visualization · 256-ch electrochemical camera · <a href="https://github.com/arghunter/Potentiostat" target="_blank" rel="noreferrer">github</a></p><h3 id="_16-mic-beamformer-asic" tabindex="-1">16-Mic Beamformer ASIC <a class="header-anchor" href="#_16-mic-beamformer-asic" aria-label="Permalink to “16-Mic Beamformer ASIC”">​</a></h3><p>16-channel PDM beamformer · DDR input · I2S output · fabricated on TT08 in SKY130B 130nm · <a href="https://github.com/arghunter/16-Mic-Beamformer-Verilog" target="_blank" rel="noreferrer">github</a></p><h3 id="pdm-pitch-filter-asic" tabindex="-1">PDM Pitch Filter ASIC <a class="header-anchor" href="#pdm-pitch-filter-asic" aria-label="Permalink to “PDM Pitch Filter ASIC”">​</a></h3><p>Configurable narrowband notch filter operating directly on PDM bitstreams · TT08 · SKY130B · <a href="https://github.com/arghunter/Customizable-PDM-Pitch-Filter-ASIC" target="_blank" rel="noreferrer">github</a></p><h3 id="pdm-correlator-asic" tabindex="-1">PDM Correlator ASIC <a class="header-anchor" href="#pdm-correlator-asic" aria-label="Permalink to “PDM Correlator ASIC”">​</a></h3><p>Cross/auto correlator for DOA and pitch detection on PDM bitstreams · TT08 · SKY130B · <a href="https://github.com/arghunter/Customizable-PDM-Cross-Correlator-ASIC" target="_blank" rel="noreferrer">github</a></p><h3 id="dnn-accelerators" tabindex="-1">DNN Accelerators <a class="header-anchor" href="#dnn-accelerators" aria-label="Permalink to “DNN Accelerators”">​</a></h3><p>Custom FPGA accelerators · PDM, Ternary, and INT8 neural network inference · MIT Open Compute Lab</p><h3 id="flamprotect" tabindex="-1">FlamProtect <a class="header-anchor" href="#flamprotect" aria-label="Permalink to “FlamProtect”">​</a></h3><p>Genetic algorithm wildfire firebreak optimization · <a href="https://github.com/arghunter/FlamProtect" target="_blank" rel="noreferrer">github</a></p><h3 id="fpga-cluster-wip" tabindex="-1">FPGA Cluster <em>(WIP)</em> <a class="header-anchor" href="#fpga-cluster-wip" aria-label="Permalink to “FPGA Cluster (WIP)”">​</a></h3><p>Multi-FPGA cluster · &gt;100 Gb/s inter-FPGA bandwidth · &gt;1.6M logic slices</p><div style="height:40px;"></div>',23),e("p",null,[e("span",{class:"newsreader"},[r('"I am always doing that which I cannot do, in order that I may learn how to do it."'),e("span",{style:{"white-space":"nowrap"}},[r(" - "),e("a",{href:"https://www.youtube.com/watch?v=6g1Yi0eSjkg",onclick:"if(window.__playMusic){event.preventDefault();window.__playMusic('6g1Yi0eSjkg','Indomitable - RWBY','Jeff Williams feat. Casey Lee Williams');"}," Pablo Picasso")])])],-1),e("div",{style:{height:"60px"}},null,-1)])])}const f=t(c,[["render",l]]);export{b as __pageData,f as default};
